package dev.heavenlyrestriction;
import io.github.manasmods.manascore.skill.api.*;
import io.github.manasmods.tensura.menu.RefiningMenu;
import net.minecraft.core.registries.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.storage.loot.*;
import net.minecraft.world.level.storage.loot.parameters.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import net.neoforged.neoforge.event.level.BlockDropsEvent;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
import static dev.heavenlyrestriction.TestFixtures.*;

@GameTestHolder(HeavenlyRestriction.ID) @PrefixGameTestTemplate(false)
public final class ProspectorGameTests {
    private static ManasSkillInstance learn(ServerPlayer p){RestrictionData.learnReward(p,HeavenlyRestriction.PROSPECTOR.get());var i=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.PROSPECTOR.get()).orElseThrow();i.setMastery(0);i.onToggleOn(p);return i;}
    private static net.minecraft.core.Holder<Enchantment> enchant(ServerPlayer p,net.minecraft.resources.ResourceKey<Enchantment> key){return p.registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolderOrThrow(key);}
    @GameTest(template="empty",timeoutTicks=100)
    public static void nativeBreakSpeedRequiresLearnedToggleAndStopsImmediately(GameTestHelper h){var p=player(h);var event=new PlayerEvent.BreakSpeed(p,Blocks.STONE.defaultBlockState(),4,p.blockPosition());ProspectorMining.speed(event);h.assertTrue(event.getNewSpeed()==4,"Missing skill increased speed");h.assertTrue(io.github.manasmods.tensura.menu.ReincarnationMenu.getSkillPool().contains(HeavenlyRestriction.PROSPECTOR.get()),"Prospector missing from the actual starting roll pool");var i=learn(p);h.assertTrue(!ChainedReincarnation.blocked(HeavenlyRestriction.PROSPECTOR.get(),p),"Free non-copying utility was blacklisted for Fettered Human");ProspectorMining.speed(event);h.assertTrue(event.getNewSpeed()==6,"Mining speed is not +50%");i.onToggleOff(p);event.setNewSpeed(4);ProspectorMining.speed(event);h.assertTrue(event.getNewSpeed()==4,"Disabled passive retained bonus");i.setMastery(-1);i.onToggleOn(p);ProspectorMining.speed(event);h.assertTrue(event.getNewSpeed()==4,"Unlearned skill granted a bonus");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void fortuneAddsThreeWithoutEditingTheHeldItem(GameTestHelper h){var p=player(h);learn(p);var tool=new ItemStack(Items.DIAMOND_PICKAXE);tool.setDamageValue(17);tool.enchant(enchant(p,Enchantments.FORTUNE),3);tool.enchant(enchant(p,Enchantments.UNBREAKING),2);var copy=ProspectorMining.lootTool(p,tool);h.assertTrue(copy!=tool && copy.getDamageValue()==17,"Loot copy changed durability");h.assertTrue(EnchantmentHelper.getItemEnchantmentLevel(enchant(p,Enchantments.FORTUNE),copy)==6,"Fortune III did not become effective Fortune VI");h.assertTrue(EnchantmentHelper.getItemEnchantmentLevel(enchant(p,Enchantments.UNBREAKING),copy)==2,"Other enchants were lost");h.assertTrue(EnchantmentHelper.getItemEnchantmentLevel(enchant(p,Enchantments.FORTUNE),tool)==3,"Actual tool was modified");h.succeed();}
    private static int diamonds(ServerPlayer p,ItemStack tool){int n=0;for(int k=0;k<1024;k++)for(var stack:Block.getDrops(Blocks.DIAMOND_ORE.defaultBlockState(),p.serverLevel(),p.blockPosition(),null,p,tool))if(stack.is(Items.DIAMOND))n+=stack.getCount();return n;}
    @GameTest(template="empty",timeoutTicks=100)
    public static void actualBlockLootUsesFortuneSixAndPreservesSilkTouch(GameTestHelper h){var p=player(h);var i=learn(p);var tool=new ItemStack(Items.DIAMOND_PICKAXE);tool.enchant(enchant(p,Enchantments.FORTUNE),3);i.onToggleOff(p);int normal=diamonds(p,tool);i.onToggleOn(p);int added=diamonds(p,tool);h.assertTrue(added>normal*1.3,"Native diamond loot ignored Prospector: "+normal+" vs "+added);i.onToggleOff(p);tool.enchant(enchant(p,Enchantments.FORTUNE),6);int six=diamonds(p,tool);h.assertTrue(Math.abs(added-six)<500,"Loot differs from actual Fortune VI: "+added+" vs "+six);tool.enchant(enchant(p,Enchantments.SILK_TOUCH),1);i.onToggleOn(p);var drops=Block.getDrops(Blocks.DIAMOND_ORE.defaultBlockState(),p.serverLevel(),p.blockPosition(),null,p,tool);h.assertTrue(drops.size()==1 && drops.getFirst().is(Items.DIAMOND_ORE) && drops.getFirst().getCount()==1,"Silk Touch was bypassed");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void findTableIsRareWeightedAndGatesInvalidMining(GameTestHelper h){var p=player(h);learn(p);var tool=new ItemStack(Items.DIAMOND_PICKAXE);var params=new LootParams.Builder(h.getLevel()).withParameter(LootContextParams.ORIGIN,p.position()).withParameter(LootContextParams.BLOCK_STATE,Blocks.STONE.defaultBlockState()).withParameter(LootContextParams.TOOL,tool).withParameter(LootContextParams.THIS_ENTITY,p).create(LootContextParamSets.BLOCK);var table=p.server.reloadableRegistries().getLootTable(ProspectorMining.FINDS);int found=0;var random=net.minecraft.util.RandomSource.create(541980);for(int n=0;n<10000;n++)for(var stack:table.getRandomItems(params,random)){found++;h.assertTrue(stack.getCount()==1,"One find dropped multiple resources");}h.assertTrue(found>=60 && found<=150,"One-percent table rate is wrong: "+found);
        for(var state:List.of(Blocks.COBBLESTONE.defaultBlockState(),Blocks.DIRT.defaultBlockState())){var drops=new ArrayList<net.minecraft.world.entity.item.ItemEntity>();ProspectorMining.finds(new BlockDropsEvent(h.getLevel(),p.blockPosition(),state,null,drops,p,tool));h.assertTrue(drops.isEmpty(),"Finds applied outside stone/deepslate");}
        var bad=new ArrayList<net.minecraft.world.entity.item.ItemEntity>();ProspectorMining.finds(new BlockDropsEvent(h.getLevel(),p.blockPosition(),Blocks.STONE.defaultBlockState(),null,bad,p,ItemStack.EMPTY));h.assertTrue(bad.isEmpty(),"Bare hands produced resources");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void magicOreAndVanillaFamiliesHaveDistinctMarkers(GameTestHelper h){var magic=BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.parse("tensura:magic_ore"));var info=ProspectorOres.kind(magic.defaultBlockState());h.assertTrue(info!=null && info.family().equals("magic_ore"),"Tensura magic ore not detected");var diamond=ProspectorOres.kind(Blocks.DIAMOND_ORE.defaultBlockState());var iron=ProspectorOres.kind(Blocks.IRON_ORE.defaultBlockState());h.assertTrue(diamond.color()!=iron.color() && diamond.glyph()!=iron.glyph() && info.color()!=diamond.color(),"Ore indicators do not differ");h.assertTrue(diamond.family().equals(ProspectorOres.kind(Blocks.DEEPSLATE_DIAMOND_ORE.defaultBlockState()).family()),"Deepslate variant lost its family");h.assertTrue(ProspectorOres.kind(Blocks.STONE.defaultBlockState())==null && ProspectorOres.kind(Blocks.DIAMOND_BLOCK.defaultBlockState())==null,"Ordinary/resource blocks counted as ores");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void nativeRefiningConsumesIngredientsAndPersistsOutput(GameTestHelper h){var p=player(h);var i=learn(p);i.onToggleOff(p);HeavenlyRestriction.PROSPECTOR.get().onPressed(i,p,0,0);h.assertTrue(p.containerMenu instanceof RefiningMenu,"Refine did not open Tensura's actual menu");var menu=(RefiningMenu<?>)p.containerMenu;menu.brewingContainer.setItem(0,new ItemStack(Items.GLASS_BOTTLE));var grass=BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("tensura:hipokute_grass"));menu.brewingContainer.setItem(3,new ItemStack(grass));h.assertTrue(menu.clickMenuButton(p,2),"Native brew button failed");HeavenlyRestriction.PROSPECTOR.get().onTick(i,p);h.assertTrue(menu.brewingContainer.isEmpty() && menu.resultContainer.getItem(0).is(BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("tensura:high_potion"))),"Actual refining recipe failed");p.closeContainer();var restored=ManasSkillInstance.fromNBT(i.toNBT());var storage=HeavenlyRestriction.PROSPECTOR.get().getSpatialStorage(restored,p.registryAccess());h.assertTrue(storage.getItem(19).getCount()==1,"Closed/serialized refinement lost its output");h.succeed();}
}
